{
  "headline": "Aztreonam is not on FDA's shortage list as of 2026-10-21; current inventory provides 10.1 to 19.8 days on hand across three sites",
  "headline_cites": ["D4", "D1", "D2", "D3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include aztreonam as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East holds 261 vials of the 1 g injection at 13.2 vials per day, giving 19.8 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 255 vials at 15.4 vials per day, giving 16.5 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale Lakeside holds 42 vials at 4.1 vials per day, giving 10.1 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "The rule‑based alternate manufacturer ranked first is E.R. Squibb & Sons, L.L.C., which is also not on FDA's shortage list today and operates from the Bristol‑Myers Squibb Company Princeton plant.",
      "cites": ["D5"]
    },
    {
      "text": "A secondary alternate is Fresenius Kabi USA, LLC, not on the shortage list, whose plant last received a VAI classification on 2023-10-13.",
      "cites": ["D6"]
    },
    {
      "text": "A third alternate is Hospira, Inc., not on the shortage list, though its label names no plant we could place.",
      "cites": ["D7"]
    }
  ]
}
